<template>
  <div class="reset-password-page">
    <el-card class="reset-password-card" shadow="always">
      <template #header>
        <div class="page-header">
          <h1>重置密码</h1>
          <p>请输入新密码</p>
        </div>
      </template>

      <el-form :model="form" :rules="rules" ref="formRef" @keyup.enter="handleSubmit">
        <el-form-item prop="newPassword">
          <el-input
            v-model="form.newPassword"
            type="password"
            placeholder="新密码"
            :prefix-icon="Lock"
            size="large"
            show-password
          />
        </el-form-item>
        <el-form-item prop="confirmPassword">
          <el-input
            v-model="form.confirmPassword"
            type="password"
            placeholder="确认新密码"
            :prefix-icon="Lock"
            size="large"
            show-password
          />
        </el-form-item>
        <el-form-item>
          <el-button
            type="primary"
            size="large"
            :loading="loading"
            @click="handleSubmit"
            style="width: 100%"
          >
            重置密码
          </el-button>
        </el-form-item>
      </el-form>

      <div class="actions">
        <router-link to="/login">返回登录</router-link>
      </div>
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { reactive, ref, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import type { FormInstance, FormRules } from 'element-plus'
import { ElMessage } from 'element-plus'
import { Lock } from '@element-plus/icons-vue'
import { confirmPasswordReset } from '@/api/auth'
import { showError } from '@/utils/error'

const route = useRoute()
const router = useRouter()

const form = reactive({
  newPassword: '',
  confirmPassword: '',
})

const loading = ref(false)
const token = ref('')
const formRef = ref<FormInstance>()

const validateConfirmPassword = (_rule: any, value: string, callback: Function) => {
  if (value !== form.newPassword) {
    callback(new Error('两次输入的密码不一致'))
  } else {
    callback()
  }
}

const rules: FormRules = {
  newPassword: [
    { required: true, message: '请输入新密码', trigger: 'blur' },
    { min: 6, message: '密码长度不能少于 6 位', trigger: 'blur' },
  ],
  confirmPassword: [
    { required: true, message: '请确认新密码', trigger: 'blur' },
    { validator: validateConfirmPassword, trigger: 'blur' },
  ],
}

onMounted(() => {
  const queryToken = route.query.token
  token.value = typeof queryToken === 'string' ? queryToken : ''
})

async function handleSubmit() {
  if (!formRef.value) return

  try {
    await formRef.value.validate()
  } catch {
    return
  }

  if (!token.value) {
    ElMessage.error('重置链接无效或已过期')
    return
  }

  loading.value = true

  try {
    await confirmPasswordReset(token.value, form.newPassword)
    ElMessage.success('密码已重置，请使用新密码登录')
    router.push('/login')
  } catch (error) {
    showError(error, '重置失败')
  } finally {
    loading.value = false
  }
}
</script>

